@Composable
private fun SearchBar(
    modifier: Modifier = Modifier,
    query: String,
    results: Pair<Int, Int>?,
    onQueryChanged: (String?) -> Unit,
    onNext: (SearchDirection) -> Unit,
) {
    val focusRequester = remember {
        FocusRequester()
    }
    val keyboard = LocalSoftwareKeyboardController.current

    Row(
        modifier = Modifier
            .fillMaxWidth()
            .background(MaterialTheme.colorScheme.background)
            .padding(Spacing.TINY)
            .shadow(elevation = 1.dp)
            .then(modifier),
        horizontalArrangement = Arrangement.spacedBy(Spacing.TINY),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        TextField(
            value = query,
            onValueChange = onQueryChanged,
            singleLine = true,
            modifier = Modifier
                .weight(1f)
                .focusRequester(focusRequester),
            placeholder = {
                Text(text = stringResource(R.string.placeholder_documentation_search_query))
            },
            colors = TextFieldDefaults.colors(
                focusedContainerColor = Color.Transparent,
                unfocusedContainerColor = Color.Transparent,
                focusedIndicatorColor = Color.Transparent,
                unfocusedIndicatorColor = Color.Transparent,
            ),
            keyboardActions = KeyboardActions {
                onQueryChanged(null)
            },
        )

        results?.takeIf { query.isNotEmpty() }?.let { (current, total) ->
            Text(
                text = "$current/$total",
                maxLines = 1,
                fontSize = FontSize.SMALL,
            )
        }

        Row(modifier = Modifier.padding(end = Spacing.SMALL)) {
            val enabled = results?.second?.let { it > 1 } == true
            Icon(
                painterResource(R.drawable.outline_keyboard_arrow_up_24),
                contentDescription = stringResource(R.string.accessibility_search_go_to_previous),
                modifier = Modifier
                    .clickable(
                        interactionSource = remember { MutableInteractionSource() },
                        indication = ripple(bounded = false),
                        enabled = enabled,
                        onClick = {
                            onNext(SearchDirection.PREVIOUS)
                        },
                    )
                    .padding(horizontal = Spacing.SMALL)
                    .runIf(!enabled) {
                        alpha(0.3f)
                    },
            )
            Icon(
                painterResource(R.drawable.outline_keyboard_arrow_down_24),
                contentDescription = stringResource(R.string.accessibility_search_go_to_next),
                modifier = Modifier
                    .clickable(
                        interactionSource = remember { MutableInteractionSource() },
                        indication = ripple(bounded = false),
                        enabled = enabled,
                        onClick = {
                            onNext(SearchDirection.NEXT)
                        },
                    )
                    .padding(horizontal = Spacing.SMALL)
                    .runIf(!enabled) {
                        alpha(0.3f)
                    },
            )
        }

        LaunchedEffect(Unit) {
            focusRequester.requestFocus()
            delay(50.milliseconds)
            keyboard?.show()
        }
    }
}

