@Composable
fun NeuromorphicButton(
    text: String,
    modifier: Modifier = Modifier,
    onClick: () -> Unit
) {
    val isDark = isSystemInDarkTheme()
    val backgroundColor = if (isDark) Color(0xFF1F1F1F) else Color(0xFFE0E0E0)
    val lightShadow = if (isDark) Color(0xFF2A2A2A) else Color.White
    val darkShadow = if (isDark) Color.Black else Color(0xFFB0B0B0)

    var isPressed by remember { mutableStateOf(false) }
    val scope = rememberCoroutineScope()

    val scale by animateFloatAsState(
        targetValue = if (isPressed) 0.96f else 1f,
        animationSpec = tween(150),
        label = "scaleAnim"
    )

    Box(
        modifier = modifier
            .graphicsLayer {
                scaleX = scale
                scaleY = scale
            }
            .clip(RoundedCornerShape(16.dp))
            .background(backgroundColor)
            .drawBehind {
                val cornerRadius = 16.dp.toPx()
                drawRoundRect(
                    color = darkShadow,
                    topLeft = Offset(6f, 6f),
                    size = size,
                    cornerRadius = CornerRadius(cornerRadius, cornerRadius),
                    alpha = 0.4f
                )
                drawRoundRect(
                    color = lightShadow,
                    topLeft = Offset(-6f, -6f),
                    size = size,
                    cornerRadius = CornerRadius(cornerRadius, cornerRadius),
                    alpha = 0.8f
                )
            }
            .clickable(
                indication = null,
                interactionSource = remember { MutableInteractionSource() }
            ) {
                isPressed = true
                scope.launch {
                    delay(150)
                    isPressed = false
                    onClick()
                }
            },
        contentAlignment = Alignment.Center
    ) {
        Text(
            text = text,
            fontSize = 18.sp,
            fontWeight = FontWeight.Bold,
            color = if (isDark) Color.White else Color.Black,
            modifier = Modifier.padding(vertical = 14.dp)
        )
    }
}

