        var gridWidth by remember { mutableStateOf(0) }
        val cardCount = 3
        val spacing = 16.dp
        val horizontalPadding = 72.dp
        val density = LocalDensity.current

        LazyHorizontalGrid(
            rows = GridCells.Fixed(1),
            modifier = Modifier
