            horizontalArrangement = Arrangement.spacedBy(spacing),
            contentPadding = PaddingValues(horizontal = horizontalPadding)) {

            val cardWidthPx = if (gridWidth > 0) {
                with(density) {
                    val totalSpacing = spacing.toPx() * (cardCount - 1)
