@Composable
fun ChatScreen(
    userId: String,
    homeViewModel: HomeViewModel,
    navController: NavController,
) {
    var isProgress by remember {
        mutableStateOf(false)
    }
    val userState by remember {
        mutableStateOf(homeViewModel.getUserById(userId))
