@Composable
private fun HourlyTable(
    headers: List<String>,
    rows: List<HourlyTableRow>,
) {
    Column(Modifier.fillMaxSize()) {
        Row(
            Modifier
                .fillMaxWidth()
                .background(HeaderBg)
                .height(HeaderHeight),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Box(
                Modifier
                    .width(TimeColWidth)
                    .fillMaxHeight()
                    .background(HeaderBg)
                    .border(width = 0.5.dp, color = Color(0xFF37474F)),
            )
            headers.forEach { h ->
                Text(
                    text = h,
                    style = HeaderStyle,
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier
                        .weight(1f)
                        .padding(horizontal = 2.dp),
                )
            }
        }
        HorizontalDivider(color = Color(0xFF37474F), thickness = 1.dp)

        LazyColumn(Modifier.fillMaxSize()) {
            itemsIndexed(
                items = rows,
                key = { index, _ -> index },
                contentType = { _, _ -> "hourly_row" },
            ) { index, row ->
                val dataBg = if (index % 2 == 0) RowBgEven else RowBgOdd
                val timeBg = if (index % 2 == 0) TimeColumnBg else TimeColumnBgAlt
                Row(
                    Modifier
                        .fillMaxWidth()
                        .height(RowHeight)
                        .background(dataBg),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Box(
                        Modifier
                            .width(TimeColWidth)
                            .fillMaxHeight()
                            .background(timeBg)
                            .border(width = 0.5.dp, color = Color(0xFFCFD8DC)),
                        contentAlignment = Alignment.Center,
                    ) {
                        Text(
                            text = row.time,
                            style = TimeCellStyle,
                            modifier = Modifier.padding(horizontal = 2.dp),
                        )
                    }
                    row.cells.forEach { cell ->
                        Text(
                            text = cell.text,
                            fontFamily = TableFont,
                            fontWeight = FontWeight.Medium,
                            fontSize = 13.sp,
                            color = cell.color,
                            textAlign = TextAlign.Center,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                            modifier = Modifier
                                .weight(1f)
                                .padding(horizontal = 2.dp),
                        )
                    }
                }
            }
        }
    }
}

