@Composable
fun ChatScreen(
    userId: String,
    homeViewModel: HomeViewModel,
    navController: NavController,
) {
    var isProgress by remember {
        mutableStateOf(false)
    }
    val userState by remember {
        mutableStateOf(homeViewModel.getUserById(userId))
    }
    if (isProgress) {
        Box(
            modifier = Modifier.fillMaxSize(),
            contentAlignment = Alignment.Center
        ) {
            CircularProgressIndicator()
        }
    }

    val myUserId = MY_USER_ID
    isProgress = false
    val user = userState
    if (user != null) {
        val chat = Chat(
            senderImage = user.profileImage,
            receiverImage = DemoData.urls.first(),
            msgs = listOf(
                Message("Hello", "12:45pm", userId = myUserId, isSeen = true),
                Message("Hey", "12:46pm", userId = userId, isSeen = true),
                Message("How are you?", "12:47pm", userId = myUserId, isSeen = true),
                Message("I'm good, hbu?", "12:49pm", userId = userId, isSeen = true),
                Message("I'm good too, thanks", "12:53pm", userId = myUserId, isSeen = true),
                Message(
                    "What are you doing",
                    "12:56pm",
                    userId = userId,
                    isSeen = true
                ),
                Message(
                    "?",
                    "12:56pm",
                    userId = userId,
                    isSeen = true
                ),
                Message(
                    "Nothing much, just code refactoring, wbu?",
                    "1:00pm",
                    userId = myUserId,
                    isSeen = false
                ),
                Message(
                    "Just resting", "1:00pm", userId = userId,
                ),
            )
        )
        Box(modifier = Modifier.fillMaxSize()) {
            Column(
                modifier = Modifier.fillMaxSize()
            ) {
                TopAppBar(
                    title = {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            CircularImage(
                                imageUrl = user.profileImage,
                                imageSize = 50.dp,
                                modifier = Modifier.clickable {
                                    navController.navigate(
                                        "${NavigationItem.Profile.route}/${user.id}"
                                    )
                                }
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            Column {
                                Text(user.name, fontSize = 18.sp)
                                Box(
                                    Modifier
                                        .size(10.dp)
                                        .clip(CircleShape)
                                        .background(Color.Green)
                                )
                            }
                        }
                    },
                    actions = {
                        Row {
                            IconButton(onClick = { /* no-op*/ }) {
                                Icon(
                                    imageVector = Icons.Default.Menu,
                                    contentDescription = "menu",
                                    modifier = Modifier.padding(8.dp)
                                )
                            }
                        }
                    }, navigationIcon = {
                        IconButton(onClick = {
                            navController.popBackStack()
                        }) {
                            Icon(
                                imageVector = Icons.Default.ArrowBack, contentDescription = "back"
                            )
                        }
                    }
                )
                Spacer(modifier = Modifier.height(8.dp))
                LazyColumn(Modifier.padding(horizontal = 8.dp)) {
                    items(chat.msgs) {
                        if (it.userId == myUserId) {
                            ChatItem(chat.senderImage, it, true)
                        } else {
                            ChatItem(chat.receiverImage, it, false)
                        }
                    }
                    item {
                        Spacer(modifier = Modifier.height(56.dp))
                    }
                }
            }
            Row(
                Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp)
                    .clip(RoundedCornerShape(16.dp))
                    .background(MaterialTheme.colorScheme.surfaceVariant)
                    .align(Alignment.BottomCenter),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                var text by rememberSaveable {
                    mutableStateOf("")
                }
                IconButton(onClick = { /* no-op */ }) {
                    Icon(
                        painter = painterResource(id = R.drawable.ic_camera),
                        modifier = Modifier
                            .clip(CircleShape)
                            .background(LIGHT_BLUE)
                            .padding(4.dp),
                        tint = Color.White,
                        contentDescription = "Camera",
                    )
                }
                TextField(
                    value = text,
                    placeholder = {
                        Text(
                            stringResource(R.string.message_hint),
                            color = Color.Gray,
                        )
                    },
                    onValueChange = {
                        text = it
                    },
                    modifier = Modifier
                        .weight(1f)
                        .clip(RoundedCornerShape(16.dp))
                )
                IconButton(onClick = {
                    navController.navigate(NavigationItem.CreatePost.route)
                }) {
                    Icon(
                        painter = painterResource(id = R.drawable.ic_image), "Gallery",
                        tint = MaterialTheme.colorScheme.onBackground,
                        modifier = Modifier.padding(4.dp)
                    )
                }
                IconButton(onClick = { /* no-op */ }) {
                    Icon(
                        Icons.Outlined.Send, "Send",
                        tint = MaterialTheme.colorScheme.onBackground,
                    )
                }
            }
        }
    }
